// Recebe { clientes: [...] } do script Python, valida e prepara 1 item por cliente
const entrada = $input.first().json;
const body = entrada.body || entrada;
const clientes = Array.isArray(body.clientes) ? body.clientes : [];

const emailValido = (e) => typeof e === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.trim());

// Mensagens estáticas: servem de plano B caso a IA falhe
const modelos = {
  conservador: { produto: 'CDB com liquidez diária', texto: 'Pelo seu perfil conservador, o foco é segurança e previsibilidade. Uma opção a considerar é um CDB com liquidez diária, que costuma permitir resgate rápido sem grandes oscilações.' },
  moderado: { produto: 'Carteira equilibrada (renda fixa + fundos)', texto: 'Pelo seu perfil moderado, vale buscar equilíbrio entre renda fixa e uma parcela menor em fundos de maior potencial de retorno.' },
  arrojado: { produto: 'Carteira com maior parcela em renda variável', texto: 'Pelo seu perfil arrojado, você aceita mais oscilação em busca de retorno maior. Uma opção a considerar é ampliar a parcela em ações e fundos de renda variável, mantendo uma reserva em renda fixa.' }
};

const saida = [];
const ignorados = [];

for (const c of clientes) {
  if (!emailValido(c.email)) { ignorados.push(c.nome || '(sem nome)'); continue; }
  const perfilBruto = String(c.perfil || 'moderado').trim().toLowerCase();
  const perfil = modelos[perfilBruto] ? perfilBruto : 'moderado';
  const m = modelos[perfil];
  const nome = c.nome || 'cliente';
  const saldo = c.saldo ?? null;

  const prompt = `Você é um assistente de educação financeira de uma corretora. Escreva um e-mail curto (máximo 90 palavras), em português do Brasil, em tom cordial e simples.\n\nCliente: ${nome}\nPerfil de investidor: ${perfil}\nSaldo disponível: ${saldo !== null ? 'R$ ' + saldo : 'não informado'}\nProduto sugerido para o perfil: ${m.produto}\n\nRegras: chame o cliente pelo nome; explique em 1 ou 2 frases por que a opção combina com o perfil; NÃO prometa rentabilidade nem use termos como 'garantido'; deixe claro que é uma sugestão informativa. Responda apenas com o texto do e-mail, sem assunto e sem formatação.`;

  saida.push({ json: { nome, email: c.email.trim(), perfil, saldo, produto: m.produto, textoEstatico: m.texto, prompt } });
}

if (saida.length === 0) {
  return [{ json: { semClientes: true, ignorados } }];
}
return saida;

// Junta o texto da IA (ou o plano B estático) com os dados do cliente e monta o e-mail
const saida = [];
const itens = $input.all();

for (let i = 0; i < itens.length; i++) {
  const resp = itens[i].json;
  const base = $('Preparar dados').all()[i].json;

  const textoIA = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
  const usouIA = typeof textoIA === 'string' && textoIA.trim().length > 0;
  const texto = usouIA ? textoIA.trim() : `Olá, ${base.nome}! ${base.textoEstatico}`;

  const paragrafos = texto.split(/\n+/).filter(Boolean).map(p => `<p>${p}</p>`).join('');
  const html = `${paragrafos}<p><small>Mensagem informativa e educacional. Não constitui recomendação individual de investimento.</small></p><p>Atenciosamente,<br>Sua equipe de investimentos</p>`;

  saida.push({ json: {
    nome: base.nome,
    email: base.email,
    perfil: base.perfil,
    assunto: `Sugestão de investimento: ${base.produto}`,
    html,
    origemMensagem: usouIA ? 'ia' : 'estatica'
  }});
}
return saida;

const enviados = $input.all().length;
const origens = $('Montar e-mail').all().map(i => i.json.origemMensagem);
return [{ json: { ok: true, enviados, mensagensIA: origens.filter(o => o === 'ia').length, mensagensEstaticas: origens.filter(o => o === 'estatica').length } }];
